// illustrative, NOT in the repo: next name to ask under QNAME minimisation
function nextQname(zone: string, full: string): string {
  // labels of full that are below zone, plus one
  const fullLabels = full.split(".");
  const zoneLabels = zone === "" ? 0 : zone.split(".").length;
  return fullLabels.slice(fullLabels.length - zoneLabels - 1).join(".");
}
