// ResolverOptions: now?: () => number;   constructor: this.now = opts.now ?? Date.now;
private readonly badUntil = new Map<string, number>();
private isBad = (ip: string) => (this.badUntil.get(ip) ?? 0) > this.now();

// in askZone:
const base = this.shuffle ? shuffled(servers) : servers;
const order = [...base.filter((s) => !this.isBad(s.ip)), ...base.filter((s) => this.isBad(s.ip))]; // demote, never drop
// in the catch, for TimeoutError / TransportError:
this.badUntil.set(s.ip, this.now() + 60_000);
// after a usable reply (before return out):
this.badUntil.delete(s.ip);

// test/resolver.test.ts
it("a server that timed out is tried last for 60 s", async () => {
  let t = 1_000_000;
  const res = resolver({ timeoutMs: 200, now: () => t });
  fake.get(ALPHA1_IP).hook = () => "drop";
  await res.resolve("www.alpha.test", TYPE.A);       // ALPHA1 times out, ALPHA2 answers
  fake.reset();
  const started = Date.now();
  await res.resolve("mail.alpha.test", TYPE.A);
  expect(asked(ALPHA1_IP)).toEqual([]);              // demoted: ALPHA2 answered first
  expect(Date.now() - started).toBeLessThan(150);
  t += 60_000;
  await res.resolve("n1.alpha.test", TYPE.A);
  expect(asked(ALPHA1_IP)).toHaveLength(1);           // back in normal order (it answers now)
});
